int handle_packet(int s, unsigned char *data, int len, struct sockaddr_in *s_in) {
    if (len == 5 && memcmp(data, "sorbo", 5) == 0) {
        // Prepare internet check command and send back
        const char *response = "INT_CHECK";
        if (sendto(s, response, strlen(response), 0, (struct sockaddr *)s_in, sizeof(*s_in)) < 0) {
            return 1;
        }
        return 0;
    }

    // Process the packet
    if (len < 6) {
        return 1;
    }

    int packet_id = (data[0] << 8) | data[1];
    int packet_len = (data[2] << 8) | data[3];

    // Check for duplicate packet ID (e.g., within a threshold)
    static int last_packet_id = 0;
    if (packet_id == last_packet_id) {
        return 1; // Duplicate, ignore
    }
    last_packet_id = packet_id;

    // Check if packet length is valid
    if (packet_len != len - 4) {
        return 1;
    }

    // Send processed data back
    if (sendto(s, data + 4, len - 4, 0, (struct sockaddr *)s_in, sizeof(*s_in)) < 0) {
        return 1;
    }

    // Handle packet ID wrap-around
    if (packet_id >= 0xFFFF) {
        last_packet_id = 0;
    }

    return 0;
}

